Contribute to this project: Deliver statement(pages, start_token, customer_id): traverse supplied legacy page snapshots, adapt their records, and compute compatible v2 customer totals. The platform wires three independently produced functions; no live SDK service or repository checkout is needed.

Your assigned work unit is entirely contained in the JSON packet below. No project checkout, materials directory, network lookup or other contribution is needed. You may use reference_work/ as scratch space. Submit only your assigned artifact.

{
  "task_id": "debug-customer-totals",
  "title": "Debug one aggregation function",
  "artifact_kind": "files",
  "optional": false,
  "description": "Repair this failing standalone function and preserve the full stated aggregation contract.",
  "requirements": "Submit exactly the named top-level function in the specified file, without imports, classes, decorators, global state, reflection or I/O. Do not mutate inputs. Python builtins and container methods get/items/keys/values/append/extend/copy/sort/pop/add are sufficient. Local variables and helper functions are allowed. No other source file or project API is required.",
  "material_paths": [],
  "packet": {
    "version": 1,
    "operation": "debug_function",
    "runtime": "python3-stdlib",
    "dependencies": [],
    "input": {
      "signature": "customer_totals(rows, customer_id)",
      "domain": "rows is a list of dictionaries containing customer_id:string, state:string, gross_cents:integer, refund_cents:integer (0 <= refund <= gross); other fields may occur. customer_id is a string.",
      "source": "def customer_totals(rows, customer_id):\n    selected = [r for r in rows if r[\"customer\"] == customer_id and r[\"state\"] == \"settled\"]\n    return {\"customer_id\": customer_id, \"order_count\": len(selected), \"net_cents\": sum(r[\"gross_cents\"] - r[\"refund_cents\"] for r in selected)}\n",
      "failing_call": {
        "args": [
          [
            {
              "order_id": "o1",
              "customer_id": "north",
              "state": "settled",
              "gross_cents": 1200,
              "refund_cents": 200
            }
          ],
          "north"
        ],
        "error": "KeyError: 'customer'"
      },
      "rules": "Select only matching customer_id and state=\"settled\". Count every selected row, including fully refunded rows. Sum gross_cents - refund_cents. Return customer_id, order_count and net_cents; empty/no-match inputs produce count 0 and net 0."
    },
    "output": {
      "path": "customer_totals.py",
      "function": "customer_totals",
      "shape": {
        "customer_id": "string",
        "order_count": "integer",
        "net_cents": "integer"
      }
    },
    "examples": [
      {
        "args": [
          [
            {
              "order_id": "o1",
              "customer_id": "north",
              "state": "settled",
              "gross_cents": 1200,
              "refund_cents": 200
            }
          ],
          "north"
        ],
        "expected": {
          "customer_id": "north",
          "order_count": 1,
          "net_cents": 1000
        }
      }
    ]
  }
}

